package com.paygate.forwarder

import com.paygate.forwarder.crypto.DeviceSigner
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/** Expected values were generated by the server's own computeDeviceSignature(). */
class DeviceSignerTest {
    private val secret = "s3cret-key"

    @Test
    fun asciiSmsMatchesServer() {
        val sms = "You have received Tk 1,200.00 from 01712750278. Fee Tk 0.00. Balance Tk 14,500.00. " +
            "TrxID ABC1234XYZ and Ref KWNZJSYR at 13/10/2026 15:24."
        assertEquals(
            "8692f5c9f9cb690bfea12e236681f31197591f50fbdea38ba11c3a0c566d729e",
            DeviceSigner.sign(secret, "dev_test_01", 101, 1760000000, sms),
        )
    }

    @Test
    fun bengaliTextNewlineAndSymbolsMatchServer() {
        val sms = "টাকা ১,২০০ received\nTrxID 9A8B7C6D5E ✓"
        assertEquals(
            "af28f2954d22c4dad6f5b21cf2853e6be20245ab22913d0a9322685c52b33aae",
            DeviceSigner.sign(secret, "dev_test_01", 102, 1760000060, sms),
        )
    }

    @Test
    fun heartbeatPayloadMatchesServer() {
        assertEquals(
            "65ddd3cb398391a47c0ad0614b7ccaabb413003b5099adb432af9424f4522cac",
            DeviceSigner.sign(secret, "dev_test_01", 103, 1760000120, "HEARTBEAT|battery=87|charging=1|pending=3"),
        )
    }

    @Test
    fun canonicalFormatIsColonSeparated() {
        assertEquals("dev_a:7:1700000000:hello", DeviceSigner.canonical("dev_a", 7, 1700000000, "hello"))
    }

    @Test
    fun signatureIsLowercaseHex64AndDependsOnEveryInput() {
        val base = DeviceSigner.sign(secret, "d", 1, 1, "x")
        assertEquals(64, base.length)
        assertTrue(base.all { it in '0'..'9' || it in 'a'..'f' })
        assertNotEquals(base, DeviceSigner.sign("other", "d", 1, 1, "x"))
        assertNotEquals(base, DeviceSigner.sign(secret, "e", 1, 1, "x"))
        assertNotEquals(base, DeviceSigner.sign(secret, "d", 2, 1, "x"))
        assertNotEquals(base, DeviceSigner.sign(secret, "d", 1, 2, "x"))
        assertNotEquals(base, DeviceSigner.sign(secret, "d", 1, 1, "y"))
    }
}
